"use strict";
// Completionist menu. Static quest data comes from data.js (generated by tools/build/build-mod.ts);
// statuses and the player's location come from Completionist:MenuBridge through OSF UI state.

(function () {
  const DATA = window.COMPLETIONIST_DATA;
  const bridge = window.osfui;
  const demo = !bridge; // previewing in a browser: fake progress so the layout can be checked

  const NOT_STARTED = 0, IN_PROGRESS = 1, COMPLETED = 2, FAILED = 3;
  const TABS = [
    { id: "here", label: "HERE" },
    { id: "locations", label: "LOCATIONS" },
    { id: "questlines", label: "QUESTLINES" },
    { id: "activities", label: "ACTIVITIES" },
  ];
  const FILTERS = [
    { id: "all", label: "ALL", test: () => true },
    { id: "missing", label: "NOT STARTED", test: (s) => s === NOT_STARTED },
    { id: "active", label: "IN PROGRESS", test: (s) => s === IN_PROGRESS },
    { id: "done", label: "COMPLETED", test: (s) => s === COMPLETED },
  ];
  const FACTION_TAGS = {
    constellation: "CONSTELLATION", "united-colonies": "UC VANGUARD", "freestar-collective": "FREESTAR",
    "ryujin-industries": "RYUJIN", "crimson-fleet": "CRIMSON FLEET", "house-varuun": "HOUSE VA'RUUN",
    "terran-armada": "TERRAN ARMADA", "trackers-alliance": "TRACKERS",
  };
  const TYPE_NOUNS = { main: "main mission", faction: "faction mission", side: "side mission", companion: "companion mission", activity: "activity" };

  const view = {
    tab: "here",
    selected: { locations: null, questlines: null, activities: "all" },
    filter: "all",
    spoilers: readSetting("spoilers", false), // true = hide names of quests you haven't started
  };
  let statuses = new Map(); // quest id -> status; quests missing here aren't in the player's load order
  let locationChain = []; // FormIDs, most specific first

  const questsById = new Map(DATA.quests.map((q) => [q.id, q]));

  // ------------------------------------------------------------------ state from Papyrus

  function readSetting(key, fallback) {
    try {
      const value = localStorage.getItem("completionist." + key);
      return value === null ? fallback : JSON.parse(value);
    } catch (e) {
      return fallback;
    }
  }
  function writeSetting(key, value) {
    try { localStorage.setItem("completionist." + key, JSON.stringify(value)); } catch (e) { /* storage unavailable */ }
  }

  let renderQueued = false;
  function queueRender() {
    if (renderQueued) return;
    renderQueued = true;
    requestAnimationFrame(() => { renderQueued = false; render(); });
  }

  function ingestStatuses() {
    const pages = bridge.state.get("pages") || 0;
    const next = new Map();
    for (let p = 0; p < pages; p++) {
      const ids = bridge.state.get("ids" + p) || [];
      const values = bridge.state.get("status" + p) || [];
      ids.forEach((id, i) => next.set(id, values[i] ?? NOT_STARTED));
    }
    statuses = next;
    queueRender();
  }

  if (demo) {
    let seed = 11;
    const rand = () => { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; };
    DATA.quests.forEach((q) => {
      const r = rand();
      statuses.set(q.id, r < 0.38 ? COMPLETED : r < 0.48 ? IN_PROGRESS : r < 0.5 ? FAILED : NOT_STARTED);
    });
    const neon = Object.values(DATA.places).find((p) => p.name === "Neon");
    locationChain = neon ? [runtimeIdFor(neon.loc)] : [];
  } else {
    bridge.state.on("pages", ingestStatuses);
    for (let p = 0; p < 8; p++) {
      bridge.state.on("ids" + p, ingestStatuses);
      bridge.state.on("status" + p, ingestStatuses);
    }
    bridge.state.on("location", (ids) => { locationChain = Array.isArray(ids) ? ids : []; queueRender(); });
  }

  // ------------------------------------------------------------------ places

  // Runtime FormIDs carry the load-order index of their plugin, which the static data can't know.
  // Starfield.esm is always index 00; full masters match on the low 24 bits, medium masters
  // (0xFD prefix) on 16 and small masters (0xFE prefix) on 12.
  function matchesLocation(runtimeId, locKey) {
    if (!locKey) return false;
    const [plugin, hex] = locKey.split("|");
    const local = parseInt(hex, 16);
    const id = runtimeId >>> 0;
    if (plugin.toLowerCase() === "starfield.esm") return id === local;
    const top = id >>> 24;
    if (top === 0xfe) return (id & 0xfff) === (local & 0xfff);
    if (top === 0xfd) return (id & 0xffff) === (local & 0xffff);
    return (id & 0xffffff) === local;
  }
  function runtimeIdFor(locKey) {
    return parseInt(locKey.split("|")[1], 16);
  }

  function placeChain(placeKey) {
    const chain = [];
    for (let key = placeKey; key && DATA.places[key] && chain.length < 8; key = DATA.places[key].parent) {
      chain.push({ key, ...DATA.places[key] });
    }
    return chain;
  }

  // The most specific tracked place containing the player.
  function herePlace() {
    for (const runtimeId of locationChain) {
      for (const [key, place] of Object.entries(DATA.places)) {
        if (matchesLocation(runtimeId, place.loc)) return key;
      }
    }
    return null;
  }

  // ------------------------------------------------------------------ data helpers

  const available = (q) => demo || statuses.has(q.id);
  const statusOf = (q) => statuses.get(q.id) ?? NOT_STARTED;

  function tally(quests) {
    const t = { total: 0, done: 0, active: 0, failed: 0 };
    for (const q of quests) {
      if (!available(q)) continue;
      t.total++;
      const s = statusOf(q);
      if (s === COMPLETED) t.done++;
      else if (s === IN_PROGRESS) t.active++;
      else if (s === FAILED) t.failed++;
    }
    t.missing = t.total - t.done - t.active - t.failed;
    return t;
  }

  // Quests whose start place is key or lies under it.
  function questsUnder(key) {
    return DATA.quests.filter((q) => placeChain(q.place).some((p) => p.key === key));
  }

  // Location tree: systems (by size) > planets > selectable places that hold quests directly.
  function locationRows(onlyActivities) {
    const pool = DATA.quests.filter((q) => available(q) && (!onlyActivities || q.activity));
    const systems = new Map();
    const anywhere = [];
    for (const q of pool) {
      const chain = placeChain(q.place);
      const system = chain.find((p) => p.kind === "system");
      if (!system) { anywhere.push(q); continue; }
      if (!systems.has(system.key)) systems.set(system.key, { place: system, quests: [], planets: new Map() });
      const s = systems.get(system.key);
      s.quests.push(q);
      const planet = chain.find((p) => p.kind === "planet");
      const planetKey = planet ? planet.key : system.key;
      if (!s.planets.has(planetKey)) s.planets.set(planetKey, { place: planet || system, holders: new Map() });
      const holder = chain[0];
      const holders = s.planets.get(planetKey).holders;
      if (!holders.has(holder.key)) holders.set(holder.key, { place: holder, quests: [] });
      holders.get(holder.key).quests.push(q);
    }

    const rows = [];
    const byTotal = (a, b) => b.quests.length - a.quests.length || a.place.name.localeCompare(b.place.name);
    for (const s of [...systems.values()].sort(byTotal)) {
      const t = tally(s.quests);
      rows.push({ kind: "group", label: s.place.name.toUpperCase(), frac: t.done + " / " + t.total });
      const planetSize = (planet) => [...planet.holders.values()].reduce((n, h) => n + h.quests.length, 0);
      for (const planet of [...s.planets.values()].sort((a, b) => planetSize(b) - planetSize(a))) {
        if (planet.place.kind === "planet") rows.push({ kind: "subgroup", label: planet.place.name });
        for (const holder of [...planet.holders.values()].sort(byTotal)) {
          rows.push({ kind: "item", key: holder.place.key, label: holder.place.name, quests: holder.quests });
        }
      }
    }
    if (anywhere.length) {
      const t = tally(anywhere);
      rows.push({ kind: "group", label: "ANYWHERE", frac: t.done + " / " + t.total });
      rows.push({ kind: "item", key: "anywhere", label: "Encounters and events", quests: anywhere });
    }
    return rows;
  }

  function questlineRows() {
    return DATA.questlines
      .map((line) => ({ kind: "item", key: line.id, label: line.name, sub: line.group, quests: line.quests.map((id) => questsById.get(id)).filter((q) => q && available(q)) }))
      .filter((row) => row.quests.length > 0);
  }

  function activityRows() {
    const all = DATA.quests.filter((q) => q.activity && available(q));
    return [{ kind: "item", key: "all", label: "All activities", quests: all }, ...locationRows(true)];
  }

  function sideRows() {
    if (view.tab === "locations") return locationRows(false);
    if (view.tab === "questlines") return questlineRows();
    if (view.tab === "activities") return activityRows();
    return [];
  }

  // ------------------------------------------------------------------ rendering

  const el = (tag, attrs, ...children) => {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs || {})) {
      if (v === undefined || v === null || v === false) continue;
      if (k === "class") node.className = v;
      else if (k === "text") node.textContent = v;
      else if (k.startsWith("on")) node.addEventListener(k.slice(2), v);
      else node.setAttribute(k, v === true ? "" : v);
    }
    for (const child of children.flat()) if (child) node.append(child);
    return node;
  };

  const SVG = "http://www.w3.org/2000/svg";
  function statusIcon(status, onLight) {
    const svg = document.createElementNS(SVG, "svg");
    svg.setAttribute("class", "icon");
    svg.setAttribute("viewBox", "0 0 18 18");
    svg.setAttribute("aria-hidden", "true");
    const stroke = onLight ? "#0b0f14" : status === IN_PROGRESS ? "#ee8a2a" : status === FAILED ? "#d64a2c" : status === COMPLETED ? "#e9edf1" : "#8d99a6";
    const add = (name, attrs) => {
      const node = document.createElementNS(SVG, name);
      for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
      svg.append(node);
    };
    add("rect", { x: 1.5, y: 1.5, width: 15, height: 15, fill: status === COMPLETED ? stroke : "none", stroke, "stroke-width": 1.5 });
    if (status === COMPLETED) add("path", { d: "M5 9.5l2.6 2.6L13 6.5", fill: "none", stroke: onLight ? "#e9edf1" : "#0b0f14", "stroke-width": 2 });
    if (status === IN_PROGRESS) add("rect", { x: 6, y: 6, width: 6, height: 6, fill: stroke });
    if (status === FAILED) add("path", { d: "M5.5 5.5l7 7M12.5 5.5l-7 7", stroke, "stroke-width": 1.8 });
    return svg;
  }

  function tagFor(q) {
    if (q.activity) return "ACTIVITY";
    if (q.type === "faction") return FACTION_TAGS[q.faction] || "FACTION";
    if (q.type === "main") return "MAIN";
    return q.type.toUpperCase();
  }

  function renderHeader() {
    const tabs = document.getElementById("tabs");
    tabs.replaceChildren(...TABS.map((t) => el("button", { "aria-current": view.tab === t.id ? "page" : null, text: t.label, onclick: () => setTab(t.id) })));
    const quests = tally(DATA.quests.filter((q) => !q.activity));
    const activities = tally(DATA.quests.filter((q) => q.activity));
    const total = (t, label) => el("div", {},
      el("div", { class: "total-value" }, String(t.done), el("span", { text: " / " + t.total })),
      el("div", { class: "total-label", text: label }));
    document.getElementById("totals").replaceChildren(total(quests, "QUESTS"), total(activities, "ACTIVITIES"));
  }

  function renderSide(rows) {
    const side = document.getElementById("side");
    side.hidden = view.tab === "here";
    side.setAttribute("aria-label", TABS.find((t) => t.id === view.tab).label);
    side.replaceChildren(...rows.map((row) => {
      if (row.kind === "group") return el("div", { class: "group" }, el("span", { text: row.label }), el("span", { text: row.frac }));
      if (row.kind === "subgroup") return el("div", { class: "subgroup", text: row.label });
      const t = tally(row.quests);
      const selected = view.selected[view.tab] === row.key;
      const pct = t.total ? Math.round((t.done / t.total) * 100) : 0;
      return el("button", { class: "item" + (selected ? " selected" : ""), "aria-pressed": selected ? "true" : "false", onclick: () => select(row.key) },
        el("span", { class: "item-head" }, el("span", { class: "item-name", text: row.label }), el("span", { class: "item-frac", text: t.done + " / " + t.total })),
        el("span", { class: "track" }, el("span", { class: "fill", style: "width: " + pct + "%" })));
    }));
    const current = side.querySelector(".item.selected");
    if (current) current.scrollIntoView({ block: "nearest" });
  }

  function renderDetail(kicker, title, quests, options) {
    options = options || {};
    const t = tally(quests);
    const shown = quests.filter((q) => available(q) && FILTERS.find((f) => f.id === view.filter).test(statusOf(q)));
    const children = [
      el("div", {}, el("div", { class: "kicker", text: kicker }), el("h1", { class: "title", text: title })),
    ];

    if (options.chain) {
      const chain = el("div", { class: "chain", role: "img", "aria-label": t.done + " of " + t.total + " completed" });
      quests.filter(available).forEach((q, i) => {
        const s = statusOf(q);
        if (i > 0) chain.append(el("b", { class: s === COMPLETED || s === IN_PROGRESS ? "done" : "" }));
        chain.append(el("i", { class: s === COMPLETED ? "done" : s === IN_PROGRESS ? "active" : "" }));
      });
      children.push(chain);
    } else {
      const bar = el("div", { class: "segments", role: "img", "aria-label": t.done + " of " + t.total + " completed" });
      const cells = Math.min(t.total, 60);
      for (let i = 0; i < cells; i++) {
        const at = ((i + 0.5) / cells) * t.total;
        bar.append(el("i", { class: at < t.done ? "done" : at < t.done + t.active ? "active" : at < t.done + t.active + t.failed ? "failed" : "" }));
      }
      children.push(bar);
    }

    const stat = (value, label, cls) => el("div", {}, el("div", { class: "stat-value " + (cls || ""), text: String(value) }), el("div", { class: "stat-label", text: label }));
    children.push(el("div", { class: "stats" },
      stat(t.done, "COMPLETED"), stat(t.active, "IN PROGRESS", "active"), stat(t.missing, "NOT STARTED"),
      t.failed ? stat(t.failed, "FAILED", "failed") : null));

    const counts = { all: t.total, missing: t.missing, active: t.active, done: t.done };
    children.push(el("div", { class: "filters", role: "tablist", "aria-label": "Filter" },
      FILTERS.map((f) => el("button", { role: "tab", "aria-selected": view.filter === f.id ? "true" : "false", text: f.label + " " + counts[f.id], onclick: () => setFilter(f.id) }))));

    const list = el("div", { class: "list" });
    if (shown.length === 0) list.append(el("div", { class: "empty", text: "Nothing here for this filter." }));
    for (const q of shown) {
      const s = statusOf(q);
      const hide = view.spoilers && s === NOT_STARTED;
      list.append(el("div", { class: "row" },
        statusIcon(s, false),
        el("span", { class: "row-name" + (hide ? " hidden" : ""), text: hide ? "Undiscovered " + (TYPE_NOUNS[q.activity ? "activity" : q.type] || "mission") : q.name }),
        el("span", { class: "row-tag" + (q.activity ? " activity" : ""), text: tagFor(q) }),
        el("span", { class: "row-meta", text: hide ? "" : options.meta ? options.meta(q) : q.giver || "" })));
    }
    children.push(list);
    document.getElementById("detail").replaceChildren(...children);
  }

  function hubName(q) {
    const chain = placeChain(q.place);
    return chain.length ? chain[0].name : "Anywhere";
  }

  function render() {
    renderHeader();
    const rows = sideRows();
    if (view.tab !== "here") {
      const items = rows.filter((r) => r.kind === "item");
      if (!items.some((r) => r.key === view.selected[view.tab]) && items.length) view.selected[view.tab] = items[0].key;
    }
    renderSide(rows);
    renderKeys();

    if (view.tab === "here") {
      const key = herePlace();
      if (!key) {
        renderDetail("NOT IN A TRACKED LOCATION", "Here", [], {});
        return;
      }
      const chain = placeChain(key);
      renderDetail(chain.slice(1).map((p) => p.name.toUpperCase() + (p.kind === "system" ? " SYSTEM" : "")).join(" · "), chain[0].name, questsUnder(key));
    } else if (view.tab === "questlines") {
      const row = rows.find((r) => r.key === view.selected.questlines);
      if (row) renderDetail((row.sub || "").toUpperCase(), row.label, row.quests, { chain: true, meta: hubName });
    } else {
      const row = rows.find((r) => r.kind === "item" && r.key === view.selected[view.tab]);
      if (!row) return renderDetail("", "Nothing tracked", [], {});
      const chain = row.key === "all" || row.key === "anywhere" ? [] : placeChain(row.key);
      const kicker = chain.slice(1).map((p) => p.name.toUpperCase() + (p.kind === "system" ? " SYSTEM" : "")).join(" · ");
      renderDetail(kicker, row.label, row.quests, view.tab === "activities" && row.key === "all" ? { meta: hubName } : {});
    }
  }

  function renderKeys() {
    const key = (k, label, end) => el("span", { class: end ? "end" : "" }, el("kbd", { text: k }), label);
    const keys = [
      key("Q / E", "SWITCH TAB"),
      view.tab === "here" ? null : key("↑ / ↓", "SELECT"),
      key("F", "FILTER"),
      key("X", "SPOILERS: " + (view.spoilers ? "HIDDEN" : "SHOWN")),
      key("ESC", "CLOSE", true),
    ];
    document.getElementById("keys").replaceChildren(...keys.filter(Boolean));
  }

  // ------------------------------------------------------------------ input

  function setTab(id) { view.tab = id; render(); }
  function select(key) { view.selected[view.tab] = key; render(); }
  function setFilter(id) { view.filter = id; render(); }

  function moveSelection(delta) {
    const items = sideRows().filter((r) => r.kind === "item");
    if (!items.length) return;
    const at = Math.max(0, items.findIndex((r) => r.key === view.selected[view.tab]));
    select(items[Math.min(items.length - 1, Math.max(0, at + delta))].key);
  }

  document.addEventListener("keydown", (event) => {
    const key = event.key.toLowerCase();
    const tabIndex = TABS.findIndex((t) => t.id === view.tab);
    if (key === "escape" || key === "tab") {
      event.preventDefault();
      if (bridge) bridge.send("close");
    } else if (key === "q" || key === "arrowleft") {
      setTab(TABS[(tabIndex + TABS.length - 1) % TABS.length].id);
    } else if (key === "e" || key === "arrowright") {
      setTab(TABS[(tabIndex + 1) % TABS.length].id);
    } else if (key === "arrowup" || key === "w") {
      event.preventDefault();
      moveSelection(-1);
    } else if (key === "arrowdown" || key === "s") {
      event.preventDefault();
      moveSelection(1);
    } else if (key === "f") {
      const i = FILTERS.findIndex((f) => f.id === view.filter);
      setFilter(FILTERS[(i + 1) % FILTERS.length].id);
    } else if (key === "x") {
      view.spoilers = !view.spoilers;
      writeSetting("spoilers", view.spoilers);
      render();
    }
  });

  render();
})();
